export const title = "How to Choose a Desk for a Room With Baseboards and Wall Outlets";
export const metaTitle = "How to Choose a Desk for a Room With Baseboards";
export const metaDescription = "Map the wall in side view, record the baseboard projection and height, locate the outlet and installed plugs, and compare those obstacles with the desk.";
export const author = "Jamie Cole, Lead Product Researcher";
export const datePublished = "2026-11-10";
